import {escapeHTML as e} from './core.js';
const mb=n=>(Number(n||0)/1024/1024).toLocaleString('vi-VN',{maximumFractionDigits:1})+' MB';
export function storageHTML(info){
  const cloud=info.mode==='supabase',unknown=info.mode==='unknown';
  return `<section class="panel panel-pad storage-panel"><div class="row between"><h3>Lưu trữ của bạn</h3><span class="status-pill ${unknown?'warn':''}">${unknown?'Chưa kiểm tra được':cloud?'Supabase · Riêng tư':'Đang lưu local'}</span></div><p class="muted small">${unknown?'Không lấy được trạng thái lưu trữ. Kiểm tra kết nối rồi thử lại.':cloud?'Transcript, tiến độ và từ vựng được lưu trên Supabase. Audio được nghe trực tiếp từ kho riêng tư; file mới chỉ giữ audio sau khi nén và xác minh.':'Bài cá nhân và tiến độ hiện vẫn nằm trên máy. Chưa chuyển dữ liệu lên cloud.'}</p>${unknown?'':`<div class="storage-size"><b>${mb(info.bytes)}</b><span>${Number(info.files||0)} file ${cloud?'audio trên cloud':'đang nằm trong uploads'}</span></div>${cloud?`<div class="bar"><span style="width:${Math.min(100,Number(info.bytes||0)/Number(info.budget||900000000)*100)}%"></span></div><p class="small muted">Ngưỡng lưu của Dicta: 900 MB. Audio sau nén tối đa 45 MB/file.</p>`:''}`}<div class="row wrap"><a class="btn secondary" href="/cloud-guide.html" target="_blank" rel="noopener">${cloud?'Hướng dẫn & dọn file gốc':'Thiết lập cloud miễn phí'} ↗</a><button class="text-btn" data-action="refresh-storage">Kiểm tra lại</button></div><div class="notice">${cloud?'Dùng project Free, không nâng cấp tự động. Hết hạn mức hoặc project tạm dừng có thể làm gián đoạn việc nghe/lưu.':'Phương án đã chọn: Supabase Free, chỉ audio và transcript, không dùng gói trả phí.'} Bộ AI và mô hình vẫn cần dung lượng trên máy để nhận dạng/dịch local.</div>${info.error?`<p class="small">${e(info.error)}</p>`:''}</section>`;
}
